            for j in range(i+1, n):
                clause.append(f'~{variables[j]}')
            clauses.append(clause)
        return variables, clauses

    def generate_quasigroup(size):
        if size == 2:
            return [[0, 1], [1, 0]]
        q = []
        for i in range(size):
            row = []
            for j in range(size):
                row.append((i + j) % size)
            q.append(row)
        return q

    def is_valid_quasigroup(q, clauses):
        n = len(q)
        variables = [f'x{i}' for i in range(n)]
        assignments = {}

        def assign(var, val):
            if var not in assignments:
                assignments[var] = val

        def evaluate_clause(clause):
            return any(assignments[var] == val for var, val in zip(clause, [0, 1]))

        def backtrack(i):
            if i == n:
                return all(evaluate_clause(clause) for clause in clauses)
            for j in range(n):
                assign(variables[i], j)
                if backtrack(i + 1):
                    return True
                del assignments[variables[i]]
            return False

        return backtrack(0)

    def resolution_refutation_depth(q, clauses):
        n = len(q)
        variables = [f'x{i}' for i in range(n)]
        queue = []

        def add_clause(clause):
            queue.append(clause)

        def resolve(c1, c2):
            new_clause = set()
            for lit in c1:
                if '~' + lit not in c2:
                    new_clause.add(lit)
            return list(new_clause)

        def is_tautology(clause):
            return any(lit == '~' + lit for lit in clause)

        add_clause([f'~{variables[i]}' for i in range(n)])

        while queue:
            c1 = queue.pop(0)
            if is_tautology(c1):
                continue
            for c2 in queue:
                if any(lit == '~' + lit for lit in c2):
                    continue
                new_clause = resolve(c1, c2)
                if not new_clause:
                    return len(queue) + 1
                add_clause(new_clause)

        return len(queue)

    def quasigroup_rank(q):
        n = len(q)
        rank = 0
        for i in range(n):
